import { fileURLToPath } from 'node:url'
import { drizzle } from 'drizzle-orm/postgres-js'
import { migrate } from 'drizzle-orm/postgres-js/migrator'
import postgres from 'postgres'

/** Folder holding the SQL files generated by `drizzle-kit generate`. */
export const migrationsFolder = fileURLToPath(new URL('../drizzle', import.meta.url))

/**
 * Applies every pending migration. Safe to run on each start: Drizzle records
 * applied migrations in the `drizzle.__drizzle_migrations` table.
 */
export async function runMigrations(url: string, folder = migrationsFolder) {
  const sql = postgres(url, { max: 1, onnotice: () => {} })
  try {
    await migrate(drizzle(sql), { migrationsFolder: folder })
  } finally {
    await sql.end()
  }
}
